import classnames from "classnames";
import { useDispatch } from "react-redux";
import { clearCompleted } from "../store";

export default function Footer({ completedCount, activeCount, filter, hidden = false }) {
    const dispatch = useDispatch();

    return (
        <footer className="footer" data-testid="footer" hidden={hidden}>
            <span className="todo-count">{`${activeCount} ${activeCount === 1 ? "item" : "items"} left!`}</span>
            <ul className="filters" data-testid="footer-navigation">
                <li>
                    <a
                        className={classnames({ selected: filter === "/" || filter === "/all" })}
                        href="#/"
                    >
                        All
                    </a>
                </li>
                <li>
                    <a className={classnames({ selected: filter === "/active" })} href="#/active">Active</a>
                </li>
                <li>
                    <a className={classnames({ selected: filter === "/completed" })} href="#/completed">Completed</a>
                </li>
            </ul>
            <button
                className="clear-completed"
                hidden={completedCount === 0}
                onClick={() => dispatch(clearCompleted())}
            >
                Clear completed
            </button>
        </footer>
    );
}

import { useDispatch } from "react-redux";
import TextInput from "./text-input";
import { addTodo } from "../store";

export default function Header() {
    const dispatch = useDispatch();

    const handleSave = (text) => {
        if (text.length !== 0) dispatch(addTodo(text));
    };

    return (
        <header className="header" data-testid="header">
            <h1>todos</h1>
            <TextInput newTodo onSave={handleSave} placeholder="What needs to be done?" />
        </header>
    );
}

import { memo, useState } from "react";
import classnames from "classnames";
import { useDispatch } from "react-redux";
import TextInput from "./text-input";
import { editTodo, deleteTodo, toggleTodo } from "../store";

function Item({ todo }) {
    const dispatch = useDispatch();
    const [editing, setEditing] = useState(false);

    const handleSave = (text) => {
        if (text.length === 0) dispatch(deleteTodo(todo.id));
        else dispatch(editTodo({ id: todo.id, text }));
        setEditing(false);
    };

    const handleCancel = () => setEditing(false);

    return (
        <li
            className={classnames({ completed: todo.completed, editing })}
            data-testid="todo-item"
        >
            <div className="view">
                <input
                    className="toggle"
                    type="checkbox"
                    data-testid="todo-item-toggle"
                    checked={todo.completed}
                    onChange={() => dispatch(toggleTodo(todo.id))}
                />
                <label onDoubleClick={() => setEditing(true)} data-testid="todo-item-label">
                    {todo.text}
                </label>
                <button
                    className="destroy"
                    data-testid="todo-item-button"
                    aria-label="Delete todo"
                    onClick={() => dispatch(deleteTodo(todo.id))}
                />
            </div>
            {editing && (
                <TextInput
                    text={todo.text}
                    editing
                    onSave={handleSave}
                    onCancel={handleCancel}
                />
            )}
        </li>
    );
}

export default memo(Item);

import { useDispatch, useSelector } from "react-redux";
import { useLocation } from "react-router-dom";

import Item from "./item";
import Footer from "./footer";
import {
    selectCompletedCount,
    selectTodos,
    selectVisibleTodos,
    toggleAll,
} from "../store";

export default function Main() {
    const dispatch = useDispatch();
    const location = useLocation();
    const todos = useSelector(selectTodos);
    const visibleTodos = useSelector(selectVisibleTodos(location.pathname));
    const completedCount = useSelector(selectCompletedCount);
    const activeCount = todos.length - completedCount;
    const empty = todos.length === 0;

    return (
        <>
            <main className="main" data-testid="main" hidden={empty}>
                <div className="toggle-all-container">
                    <input
                        id="toggle-all"
                        className="toggle-all"
                        type="checkbox"
                        data-testid="toggle-all"
                        checked={!empty && completedCount === todos.length}
                        onChange={() => dispatch(toggleAll())}
                    />
                    <label className="toggle-all-label" htmlFor="toggle-all">
                        Toggle All Input
                    </label>
                </div>
                <ul className="todo-list" data-testid="todo-list">
                    {visibleTodos.map((todo) => (
                        <Item key={todo.id} todo={todo} />
                    ))}
                </ul>
            </main>
            <Footer
                completedCount={completedCount}
                activeCount={activeCount}
                filter={location.pathname}
                hidden={empty}
            />
        </>
    );
}

import { useState, useRef } from "react";
import classnames from "classnames";

export default function TextInput({
    onSave,
    onCancel,
    text = "",
    placeholder,
    editing = false,
    newTodo = false,
}) {
    const [value, setValue] = useState(text);
    const cancelled = useRef(false);

    const submit = () => {
        if (cancelled.current) {
            cancelled.current = false;
            return;
        }
        onSave(value.trim());
        if (newTodo) setValue("");
    };

    const handleKeyDown = (e) => {
        if (e.key === "Enter") {
            submit();
        } else if (e.key === "Escape" && editing && onCancel) {
            cancelled.current = true;
            onCancel();
        }
    };

    const handleBlur = () => {
        if (!newTodo) submit();
    };

    return (
        <input
            className={classnames({ edit: editing, "new-todo": newTodo })}
            type="text"
            data-testid="text-input"
            placeholder={placeholder}
            aria-label={editing ? "Edit todo" : "New todo"}
            autoFocus
            value={value}
            onBlur={handleBlur}
            onChange={(e) => setValue(e.target.value)}
            onKeyDown={handleKeyDown}
        />
    );
}

