					"You can also install the CLI manually."
			);

			return;
		}
		process.exitCode = 0;

		console.log(
			`Installing '${
				cli.package
			}' (running '${packageManager} ${installOptions.join(" ")} ${
				cli.package
			}')...`
		);

		runCommand(
			/** @type {string} */
			(packageManager),
			[...installOptions, cli.package]
		)
			.then(() => {
				runCli(cli);
			})
			.catch((err) => {
				console.error(err);
				process.exitCode = 1;
			});
