				const handler = (parser) => {
					// Handle nested requires
					parser.hooks.preStatement.tap(PLUGIN_NAME, (statement) => {
						if (
							statement.type === "FunctionDeclaration" &&
							statement.id &&
							statement.id.name === RuntimeGlobals.require
