		if (!this._exportsAreOrdered) {
			this._sortExports();
		}
		if (this._redirectTo !== undefined) {
			/** @type {Exports} */
			const map = new Map(
				Array.from(this._redirectTo.orderedExports, (item) => [item.name, item])
			);
			for (const [key, value] of this._exports) {
				map.set(key, value);
			}
