		this.handler = handler;
		/** @type {ErrorCallback[]} */
		this.callbacks = [];
		/** @type {ErrorCallback[] | undefined} */
		this._closeCallbacks = undefined;
		this.closed = false;
		this.suspended = false;
		this.blocked = false;
