const mergeMaybeArrays = (a, b) => {
	/** @type {Set<T | U | null | undefined | string | Set<T> | Set<U>>} */
	const set = new Set();
	if (Array.isArray(a)) for (const item of a) set.add(item);
	else set.add(a);
	if (Array.isArray(b)) for (const item of b) set.add(item);
	else set.add(b);
