	for (const group of queue) {
		if (group !== entrypoint) {
			groups.add(group);
		}
		for (const parent of group.parentsIterable) {
			if (parent instanceof Entrypoint) queue.add(parent);
		}
	}
	groups.add(entrypoint);

	/** @type {Set<Chunk>} */
