/** @typedef {import("../ChunkGraph").EntryModuleWithChunkGroup} EntryModuleWithChunkGroup */
/** @typedef {import("../RuntimeTemplate")} RuntimeTemplate */

const EXPORT_PREFIX = `var ${RuntimeGlobals.exports} = `;

