		for (const request of moduleRequests) {
			result.add(`export * from "${request}";\n`);
		}

		for (const [origin, used] of unknownProvidedExports) {
			exports.push([
				origin,
				`${RuntimeGlobals.exports}${propertyAccess([used])}`
			]);
		}

		return result;
