									rootOutputDir
								)} + ${RuntimeGlobals.getUpdateManifestFilename}());`,
								`require(${runtimeTemplate.renderNodePrefixForCoreModule("fs")}).readFile(filename, 'utf-8', function(err, content) {`,
								Template.indent([
