const mapObject = (obj, fn) => {
	/** @type {T} */
	const newObj = Object.create(null);
	for (const key of Object.keys(obj)) {
		newObj[/** @type {keyof T} */ (key)] = fn(
			obj[/** @type {keyof T} */ (key)],
			/** @type {keyof T} */
			(key)
		);
	}
	return newObj;
};

/**
