		const keys = [];
		/** @type {Keys[number] | null} */
		let key = context.read();
		while (key !== null) {
			keys.push(key);
			key = context.read();
		}
		for (const key of keys) {
			obj[/** @type {keyof T} */ (key)] = context.read();
		}
		return obj;
