/** @typedef {{ [p: string]: { [p: string]: EXPECTED_ANY } } | DynamicFunction} ByObject */

/**
 * Returns parsed object.
 * @template {object} T
 * @param {T} obj the object
 * @returns {ParsedObject<T>} parsed object
