/* used for things that should be hidden in the ui,
but useful for people who use screen readers */
.visually-hidden {
    border: 0;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    height: 1px;
    width: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
}

.toggle-all {
    width: 40px !important;
    height: 60px !important;
    right: auto !important;
}

.toggle-all-label {
    pointer-events: none;
}

import { mount } from "svelte";
import App from "./App.svelte";

const app = mount(App, {
    target: document.querySelector(".todoapp"),
});

export default app;

export function router(onChange) {
    let route = "all";

    function handleChange() {
        switch (window.location.hash) {
            case "#/active":
                route = "active";
                break;
            case "#/completed":
                route = "completed";
                break;
            default:
                route = "all";
        }

        onChange(route);
    }

    function init() {
        window.addEventListener("hashchange", handleChange);
    }

    return {
        init,
    };
}

