	var buf = new Buffer(10)
	for (var i = 0; i < 10; i++) {
		buf[i] = i
	}

	var ab = toArrayBuffer(buf)

	t.equals(ab.byteLength, 10, 'correct length')
	t.ok(elementsEqual(ab, buf), 'elements equal')
	t.end()
