                    break;
                case "item-title":
                    if (this["item-title"] !== undefined) {
                        this.todoText.textContent = this["item-title"];
                        this.editInput.value = this["item-title"];
                    }
                    break;
                case "item-completed":
                    this.toggleInput.checked = this["item-completed"] === "true" ? true : false;
                    break;
            }
        });
    }

