html,
body {
	margin: 0;
	padding: 0;
}

body {
	font: 16px 'Helvetica Neue', Helvetica, Arial;
	font-weight: 300;
	line-height: 1.5;
	width: auto;
	background: #fafafa;
	color: #353535;
	font-smoothing: antialiased;
}
body.learn-page{
    max-width: 1600px;
    margin: 0 auto;
}

h1,
h2,
h3,
h4,
h5,
h6 {
	font-weight: 400;
	line-height: 1.2;
	color: #000;
}

h2 {
	margin: 10px 0;
	font-size: 24px;
}

a,
.link {
	color: #9f3c3c;
	font-weight: 500;
	cursor: pointer;
}


a:hover,
.link:hover {
	color: #431919;
	text-decoration: none;
}

p {
	font-size: 16px;
	line-height: 1.5;
	font-weight: 300;
}

var {
	font-style: normal;
}

header p {
	font-size: 30px;
	line-height: 1.2;
	margin-top: 10px;
}

header nav {
	margin-top: 20px;
	font-size: 20px;
}

header nav a {
	font-weight: 200;
}

header nav a:not(:last-child) {
	margin-right: 5px;
	margin-bottom: 5px;
}

.logo {
	margin-top: 70px;
}

.logo-icon {
	display: none;
}

.row {
	margin-top: 20px;
	margin-bottom: 20px;
}

.screenshot {
	width: 100%;
	height: auto;
	max-width: 558px;
	margin-top: 12px;
	float: right;
}

.tagline2 {
	font-size: 21px;
	font-style: italic;
	margin-top: 40px;
}

.container {
	margin-top: 10px;
	margin-bottom: 20px;
}

.whats-new li {
	position: relative;
	margin: 15px 0;
	list-style: none;
}

.whats-new li:before {
	content: '✔';
	position: absolute;
	left: -20px;
}

.app-lists {
	overflow: hidden;
}

.applist {
	list-style: none;
	margin: 0;
	padding: 0;
	font-size: 17px;
	display: grid;
	grid-template-columns: 1fr 1fr 1fr;
}

.applist li {
	margin: 10px 0;
}

.applist a {
	position: relative; /* popover */
}

.applist-item {
	padding: 4px;
    display: block;
	border-radius: 4px;
}

.applist-item:hover {
	background-color: rgba(0, 0, 0, 0.1);
}

.applist-intro {
	margin: 10px 0 10px;
	font-style: italic;
}

.badge {
	font-weight: bold;
	font-size: 11px;
	color: #777;
	vertical-align: middle;
	white-space: nowrap;
	text-shadow: 0 -1px 0 rgba(255, 255, 255, 0.25);
	padding: 2px 4px;
	background-color: rgba(0, 0, 0, .1);
	border-radius: 3px;
}

.link + .badge {
	margin-left: 5px;
}

.badge:not(:last-child) {
	margin-right: 5px;
}

.badge[data-color="green"]  {
	background-color: green;
	color: white;
}

.applist .labs a,
.labs-example {
	color: #582C42;
}

.legend {
	margin-top: 20px;
	margin-left: 0;
	padding: 0;
	list-style-type: none;
	line-height: 0;
}

.legend li {
	margin-bottom: 0.5em;
}

.legend li:last-child {
	margin-bottom: 0;
}

.collapsed {
	overflow: hidden;
	max-height: 0;
	transition: max-height 0.7s ease-out;
}

.simple-dropdown {
	display: none;
}

.simple-dropdown:checked ~ .collapsed {
	max-height: 999px;
	transition: max-height 0.7s ease-in;
}

.credit {
	text-align: center;
}

.credit a {
	margin: 5px;
	white-space: nowrap;
	line-height: 50px;
	display: inline-block;
}

.credit a img {
	border-radius: 3px;
	margin-right: 5px;
}

.popover {
	margin: 0;
	cursor: default;
	color: #333;
	white-space: normal;
	z-index: 999;
}

.popover-title {
	padding: 9px 70px 9px 15px;
}

.popover-title a {
	font-size: 13px;
	position: absolute;
	right: 20px;
}

.quote {
	border: none;
	margin: 20px 0 70px 0;
}

.quote p {
	font-size: 17px;
	line-height: 1.3;
	font-style: italic;
}

.quote p:before {
	content: '“';
	font-size: 50px;
	opacity: .15;
	position: absolute;
	top: -20px;
	left: 3px;
}

.quote p:after {
	content: '”';
	font-size: 50px;
	opacity: .15;
	position: absolute;
	bottom: -42px;
	right: 3px;
}

.quote footer {
	position: absolute;
	bottom: -60px;
	left: 12px;
}

.quote footer img {
	border-radius: 3px;
}

.quote footer a {
	margin-left: 5px;
	vertical-align: middle;
}

.speech-bubble {
	position: relative;
	padding: 10px;
	background: rgba(0, 0, 0, .04);
	border-radius: 5px;
}

.speech-bubble:after {
	content: '';
	position: absolute;
	top: 100%;
	left: 20px;
	border: 13px solid transparent;
	border-top-color: rgba(0, 0, 0, .04);
}

.zocial.red {
	background-color: #b12d2b;
}

.zocial.gray {
	background-color: rgba(0, 0, 0, .5);
}

.zocial.ltgray {
	color: inherit;
	text-shadow: none;
}

.zocial.ltgray strong {
	color: #B83F45;
}

.zocial.small {
	font-size: 12px;
	padding: 2px 10px;
}

.zocial,
a.zocial {
	background: #f4f4f4;
	border: 1px solid #777;
	border-color: rgba(0, 0, 0, 0.2);
	border-bottom-color: #333;
	border-bottom-color: rgba(0, 0, 0, 0.4);
	color: white;
	cursor: pointer;
	display: inline-block;
	padding: 6px 10px;
	text-align: center;
	text-decoration: none;
	text-shadow: 0 1px 0 rgba(0, 0, 0, 0.5);
	user-select: none;
	position: relative;
	border-radius: .3em;
}

@media (max-width: 480px) {
	.credit a {
		display: block;
	}

	.applist {
		grid-template-columns: 1fr;
	}
}

@media (min-width: 481px) and (max-width: 770px) {
	.applist {
		grid-template-columns: 1fr 1fr;
	}
}

@media (max-width: 770px) {
	h2 {
		margin-top: 20px;
	}

	.row,
	.credit {
		margin-left: 10px;
		margin-right: 10px;
	}

	.logo {
		max-width: 100%;
		margin-top: 0;
	}

	.container {
		margin: auto;
	}
}

@media (min-width: 992px) {
	.logo-icon {
		display: block;
	}
}

hr {
    margin: 20px 0;
    border: 0;
    border-top: 1px dashed #c5c5c5;
    border-bottom: 1px dashed #f7f7f7;
}

/* Learn page specifics*/
.learn-page > .learn {
    position: fixed;
    height: 100%;
    width: 272px;
    top: 0px;
    left: -300px;
    overflow-y: auto;
    padding: 0px;
    background-color: rgba(255, 255, 255, .6);
    transition-property: left;
    transition-duration: 500ms;
    line-height: 36px;
    text-indent: 20px;
}
.learn-page nav a {
    display: block;
}

.learn nav a:hover, .learn-page nav a.selected {
    background-color: #b83f45;
    color: #ffffff;
}

.learn .content {
    padding: 15px;
}
.learn-page header {
    width: 100%;
}

div.learn {
    margin: 50px 20px 20px 20px;
    padding: 20px;
    background: #eee;
}

@media (min-width: 899px) {
    .learn-page {
        width: auto;
        padding-left: 300px;
    }

    .learn-page > .learn {
        left: 8px;
    }
}

