		directories.forEach(function (destPath) {
			wrench.copyDirSyncRecursive(
				sourceTodoMvcCommon,
				destPath,
				{
					forceDelete: true,
					preserveFiles: false
				},
				function () {
					console.log(arguments);
				});
		});
	});
};

